def transform_v2(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            cell_val = grid[r][c]

            if cell_val != 0:
                # Check orth same-color neighbors
                orth_same = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == cell_val:
                        orth_same += 1

                # Rule: only keep if 2-3 same-color orth neighbors
                if 2 <= orth_same <= 4:
                    result[r][c] = cell_val
                else:
                    # Remove - become 0
                    pass
            else:
                # Check 8-neighbor majority
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbors.append(grid[nr][nc])

                if neighbors:
                    cnt = Counter(neighbors)
                    # Most common
                    most_common = cnt.most_common(1)
                    if most_common and most_common[0][0] != 0:
                        if most_common[0][1] >= 4:  # threshold: need 4+ of same color
                            result[r][c] = most_common[0][0]
                    elif most_common and most_common[0][0] == 0 and most_common[0][1] >= 5:
                        result[r][c] = 0
                    # else: stay 0

    return result

