def transform_v8(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            cell_val = grid[r][c]

            if cell_val != 0:
                orth_same = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == cell_val:
                        orth_same += 1

                if cell_val == 1:
                    # 1s: keep if orth_same >= 1 AND has 1 above OR r == 0
                    if orth_same >= 1 and (r == 0 or grid[r-1][c] == 1):
                        result[r][c] = 1
                elif cell_val == 8:
                    # 8s: keep if orth_same >= 2 AND zero_count < 5
                    zero_count = 0
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == 0:
                                    zero_count += 1
                    if orth_same >= 2 and zero_count < 5:
                        result[r][c] = 8
                elif cell_val in [2, 3, 4, 5, 6, 7, 9]:
                    result[r][c] = 0 # drop other colors

            else:
                # Fill zeros - only 1,8 in 8-neigh majority
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] in [1, 8]:
                                neighbors.append(grid[nr][nc])

                if neighbors:
                    c1 = neighbors.count(1)
                    c8 = neighbors.count(8)
                    if c1 >= 4:
                        result[r][c] = 1
                    elif c8 >= 4:
                        result[r][c] = 8

    return result

